async flush() {
	if (this._flushed) {
		return;
	}

	this._flushed = true;

	try {
		this._attachAbortListener();

		if (this.destroyed) {
			return;
		}

		await this._finalizeBody();

		if (this.destroyed) {
			return;
		}

		this._hasWritableBody = this._canWriteBody();

		await this._makeRequest();

		if (this.destroyed) {
			this._request?.destroy();
			return;
		}

		// Queued writes etc.
		for (const job of this._jobs) {
			job();
		}

